// ================= KONFIGURASI — UBAH DI SINI =================
// Kerangka Andry Hakim (riset publik): cari saham KECIL yang sedang BERTRANSFORMASI
// lewat aksi korporasi (pengendali baru / backdoor, right issue awal, inbreng aset),
// dipegang PENGENDALI yang kuat dan berkomitmen, belum telanjur naik (anti-FOMO).
const OWNER_WHITELIST = [
  'Prajogo Pangestu',
  'Barito Pacific',
  // Kendaraan Agung Sedayu Group & Salim Group (dari data Sectors, ownership PANI)
  'Multi Artha Pratama',
];
const WHITELIST_SEBAGAI_SARINGAN = false; // true = right issue di luar whitelist dibuang (hemat kredit)

// Peristiwa (katalis)
const MAX_RI_KE = 2;              // right issue ke-1/ke-2 = katalis
const PENGENDALI_PCT = 50;        // pihak baru melewati 50% = pengambilalihan
const AKUISISI_MIN_PCT = 20;      // atau pihak baru naik >= 20 poin sekaligus
const PIHAK_BARU_MAX_PCT = 5;     // "pihak baru" = kepemilikan sebelumnya < 5%

// Gerbang pasar (data harga point-in-time)
const MAX_MCAP_PRA = 10e12;       // kapitalisasi sebelum peristiwa > Rp10 T = terlalu besar untuk multibagger
const MIN_LIKUIDITAS = 50e6;      // median nilai transaksi 20 hari < Rp50 juta = tidak bisa dibeli

// Pemeriksaan
const GROWTH_MIN = 0.2;           // pendapatan tahunan naik >= 20%
const MAX_OWNER_JUAL_PCT = 1;     // pemegang besar jual >= 1% dalam 12 bulan = gugur
const MIN_HOLDER_PCT = 5;         // pemegang besar = kepemilikan >= 5%
const DILUSI_EKSTREM = 10;        // saham baru >= 10x saham lama
const TOLAK_JENIS = ['restrukturisasi_internal', 'konsolidasi_atau_tender_offer', 'penyelamatan_keuangan'];

const MAX_KANDIDAT = 10;          // batas kandidat per run (hemat kredit)
const SKOR_MINIMUM = 60;
// ===============================================================

const tz = 'Asia/Jakarta';
const input = $input.first()?.json ?? {};
const today = DateTime.now().setZone(tz).startOf('day');
const asOf = input.as_of_date
  ? DateTime.fromISO(String(input.as_of_date), { zone: tz }).startOf('day')
  : today;
const mode = input.mode === 'backtest' ? 'backtest' : 'live';
const minD = (a, b) => (a < b ? a : b);
const ujung = minD(asOf, today);

// Kalender RI. Live: -30/+30 hari. Backtest: 60 hari sampai as_of (anti look-ahead).
const calStart = mode === 'live' ? asOf.minus({ days: 30 }) : asOf.minus({ days: 59 });
const calEnd = mode === 'live' ? asOf.plus({ days: 30 }) : asOf;
// Filings pasar (deteksi pengambilalihan). Live: 7 hari. Backtest: 60 hari.
const cocStart = mode === 'live' ? ujung.minus({ days: 7 }) : ujung.minus({ days: 59 });
// Filings per emiten (perilaku owner 12 bulan)
const filStart = ujung.minus({ days: 365 });
// Harga 90 hari sampai as_of (ukuran, likuiditas, harga tebus vs pasar, anti-FOMO)
const priceStart = ujung.minus({ days: 89 });
// Berita 120 hari sampai as_of (narasi transformasi)
const newsStart = ujung.minus({ days: 120 });
// Kinerja 90 hari SETELAH sinyal (hanya backtest, untuk evaluasi; tidak memengaruhi skor)
const perfStart = asOf.plus({ days: 1 });
const perfEnd = minD(asOf.plus({ days: 90 }), today);
// Tahun laporan tahunan yang sudah terbit per as_of (laporan audit keluar ~April)
const finYear = asOf.month >= 5 ? asOf.year - 1 : asOf.year - 2;

const clean = (s) => String(s).replace(/'/g, '');
const ownerWhere = OWNER_WHITELIST.length
  ? OWNER_WHITELIST.map((n) => `major_shareholders_name like '%${clean(n)}%'`).join(' or ')
  : "symbol = 'ZZZZ'";

return [{
  json: {
    mode,
    as_of_date: asOf.toISODate(),
    calStart: calStart.toISODate(), calEnd: calEnd.toISODate(),
    cocStart: cocStart.toISODate(), cocEnd: ujung.toISODate(),
    filStart: filStart.toISODate(), filEnd: ujung.toISODate(),
    priceStart: priceStart.toISODate(), priceEnd: ujung.toISODate(),
    newsStart: newsStart.toISODate(), newsEnd: ujung.toISODate(),
    perfStart: perfStart.toISODate(), perfEnd: perfEnd.toISODate(),
    perfAda: mode === 'backtest' && perfStart <= perfEnd,
    finYear,
    ownerWhere,
    config: { OWNER_WHITELIST, WHITELIST_SEBAGAI_SARINGAN, MAX_RI_KE, PENGENDALI_PCT, AKUISISI_MIN_PCT,
              PIHAK_BARU_MAX_PCT, MAX_MCAP_PRA, MIN_LIKUIDITAS, GROWTH_MIN, MAX_OWNER_JUAL_PCT,
              MIN_HOLDER_PCT, DILUSI_EKSTREM, TOLAK_JENIS, MAX_KANDIDAT, SKOR_MINIMUM },
    run_started_at: DateTime.now().setZone(tz).toISO(),
  },
}];

// TAHAP 1 — PERISTIWA: right issue awal atau pengambilalihan oleh pihak baru
const cfg = $('Konfigurasi').first().json;
const C = cfg.config;
const cal = $('Kalender Right Issue').first().json || {};
const scr = $('Screener Owner Whitelist').first().json || {};
const norm = (s) => String(s || '').toUpperCase().replace('.JK', '');
const namaN = (x) => String(x || '').toLowerCase().replace(/\b(pt|tbk)\b|[.,]/g, '').replace(/\s+/g, ' ').trim();

const ownerSet = new Set((scr.results || []).map((r) => norm(r.symbol)));
const kandidat = {};

// 1a) Right issue (ex_date terbaru per emiten)
const riPerSym = {};
for (const ri of cal.right_issue || []) {
  const s = norm(ri.symbol);
  if (!riPerSym[s] || String(ri.ex_date) > String(riPerSym[s].ex_date)) riPerSym[s] = ri;
}
for (const [s, ri] of Object.entries(riPerSym)) {
  if (C.WHITELIST_SEBAGAI_SARINGAN && C.OWNER_WHITELIST.length && !ownerSet.has(s)) continue;
  kandidat[s] = { symbol: s, ri };
}

// 1b) Pengambilalihan oleh PIHAK BARU (semua halaman filings, semua jenis transaksi)
const pages = $('Filings Pasar (Pengambilalihan)').all().map((i) => i.json || {});
const rows = pages.flatMap((p) => p.results || []);
let akuisisi = 0, abaikan = 0;
for (const f of rows) {
  const b = Number(f.share_percentage_before ?? 0);
  const a = Number(f.share_percentage_after ?? 0);
  const melewati = b < C.PENGENDALI_PCT && a >= C.PENGENDALI_PCT;
  const lompatan = a - b >= C.AKUISISI_MIN_PCT;
  if (!melewati && !lompatan) continue;
  // Pihak lama yang menambah (konsolidasi, tender offer induk) BUKAN transformasi
  if (b >= C.PIHAK_BARU_MAX_PCT) { abaikan++; continue; }
  // Emiten ini sendiri yang membeli perusahaan lain
  const target = String(f.title || '').split(/shares of/i)[1];
  if (target && namaN(target).includes(namaN(f.holder_name))) { abaikan++; continue; }
  akuisisi++;
  const s = norm(f.symbol);
  kandidat[s] = kandidat[s] || { symbol: s };
  const tgl = String(f.timestamp || '').slice(0, 10);
  if (!kandidat[s].coc || tgl > kandidat[s].coc.tanggal) {
    kandidat[s].coc = { jenis: melewati ? 'pengendali baru' : 'pemegang strategis baru', pembeli: f.holder_name,
      sebelum: b, sesudah: a, tanggal: tgl, harga: f.price ?? null, grup: f.idx_conglomerates_group_slug || [] };
  }
}

let list = Object.values(kandidat);
list.sort((x, y) => ((y.coc ? 1 : 0) - (x.coc ? 1 : 0))
  || String(y.ri?.ex_date || y.coc?.tanggal || '').localeCompare(String(x.ri?.ex_date || x.coc?.tanggal || '')));
const terpotong = list.length > C.MAX_KANDIDAT;
list = list.slice(0, C.MAX_KANDIDAT);

const stats = {
  ri_dalam_jendela: Object.keys(riPerSym).length,
  akuisisi_terdeteksi: akuisisi,
  akuisisi_diabaikan: abaikan,
  kandidat: list.length,
  terpotong,
  filings_dibaca: rows.length,
  filings_total_tersedia: pages[0]?.pagination?.total_count ?? null,
  kalender_error: !!cal.error,
};
if (!list.length) return [{ json: { _empty: true, tahap: 'peristiwa', stats } }];
return list.map((k) => ({
  json: { ...(k.ri || {}), symbol: k.symbol, is_ri: !!k.ri, is_coc: !!k.coc, coc: k.coc || null,
          owner_whitelist: ownerSet.has(k.symbol), stats },
}));

// TAHAP 2 — GERBANG PASAR (point-in-time, dari harga 90 hari sampai as_of)
const cfg = $('Konfigurasi').first().json;
const C = cfg.config;
const kand = $('Gabung kandidat').all();
const parse = (j) => {
  if (!j || j.error) return null;
  let raw = j.raw ?? j.data ?? j;
  if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { return null; } }
  if (Array.isArray(raw)) return raw;
  if (raw && Array.isArray(raw.results)) return raw.results;
  return null;
};
const median = (a) => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

const lolos = [], ditolak = [];
$input.all().forEach((it, i) => {
  const k = kand[i].json;
  const data = parse(it.json);
  const rows = (data || []).filter((r) => r && r.date && r.close > 0 && r.date <= cfg.priceEnd)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const ada = rows.length > 0;
  const last = ada ? rows[rows.length - 1] : null;
  const tglPeristiwa = k.is_coc && (!k.is_ri || k.coc.tanggal < k.ex_date) ? k.coc.tanggal : (k.ex_date || k.coc?.tanggal);
  let pra = null;
  for (const r of rows) if (r.date < tglPeristiwa) pra = r;
  if (!pra) pra = last;
  const mcapPra = pra?.market_cap ?? null;
  const minClose = ada ? Math.min(...rows.map((r) => r.close)) : null;
  const kenaikan = ada && minClose ? last.close / minClose : null;
  const likuiditas = median(rows.slice(-20).map((r) => r.close * (r.volume || 0)));
  const diskon = k.is_ri && k.price && pra?.close ? k.price / pra.close - 1 : null;
  const dilusi = k.is_ri && k.old_ratio && k.new_ratio ? k.new_ratio / k.old_ratio : null;
  const hargaAkuisisiVsPasar = k.is_coc && k.coc.harga && pra?.close ? k.coc.harga / pra.close - 1 : null;

  const pasar = {
    data_harga_ada: ada, harga_asof: last?.close ?? null, tanggal_harga: last?.date ?? null,
    mcap_pra: mcapPra, likuiditas_median: likuiditas, kenaikan_90h: kenaikan ? +kenaikan.toFixed(2) : null,
    diskon_tebus: diskon != null ? +diskon.toFixed(3) : null, dilusi: dilusi != null ? +dilusi.toFixed(2) : null,
    harga_akuisisi_vs_pasar: hargaAkuisisiVsPasar != null ? +hargaAkuisisiVsPasar.toFixed(3) : null,
  };
  const alasan = [];
  if (ada && mcapPra != null && mcapPra > C.MAX_MCAP_PRA) alasan.push(`kapitalisasi Rp${(mcapPra / 1e12).toFixed(1)} T terlalu besar`);
  if (ada && likuiditas != null && likuiditas < C.MIN_LIKUIDITAS) alasan.push(`tidak likuid (Rp${Math.round(likuiditas / 1e6)} juta/hari)`);
  if (alasan.length) ditolak.push({ symbol: k.symbol, alasan: alasan.join(', ') });
  else lolos.push({ ...k, pasar });
});

if (!lolos.length) return [{ json: { _empty: true, tahap: 'gerbang pasar', ditolak, stats: kand[0]?.json?.stats } }];
return lolos.map((k) => ({ json: { ...k, ditolak_gerbang: ditolak } }));

const cfg = $('Konfigurasi').first().json;
const C = cfg.config;
const syms = $input.all().map((i) => i.json.symbol);
const list = '[' + syms.flatMap((s) => [`'${s}'`, `'${s}.JK'`]).join(', ') + ']';
const Y = cfg.finYear;
return [{
  json: {
    whereTumbuh: `symbol in ${list} and revenue[${Y}] > revenue[${Y - 1}] * ${1 + C.GROWTH_MIN}`,
    whereTurnaround: `symbol in ${list} and earnings[${Y}] > 0 and earnings[${Y - 1}] < 0`,
    whereEkuitasNegatif: `symbol in ${list} and total_equity[${Y}] < 0`,
  },
}];

const norm = (s) => String(s || '').toUpperCase().replace('.JK', '');
const ambil = (n) => { const r = $(n).first().json || {}; return { ok: !r.error, s: new Set((r.results || []).map((x) => norm(x.symbol))) }; };
const tumbuh = ambil('Screener Pendapatan Tumbuh');
const turn = ambil('Screener Turnaround Laba');
const neg = ambil('Screener Ekuitas Negatif');
const cfg = $('Konfigurasi').first().json;
return $('Gerbang Pasar').all().map((it) => {
  const s = it.json.symbol;
  return { json: { ...it.json, tumbuh: tumbuh.s.has(s), turnaround: turn.s.has(s), ekuitas_negatif: neg.s.has(s),
                   fundamental_tahun: cfg.finYear, fundamental_dicek: tumbuh.ok && turn.ok } };
});

// Right issue ke-berapa (anti look-ahead: hanya RI dengan ex_date <= peristiwa)
const cfg = $('Konfigurasi').first().json;
const kand = $('Kembalikan kandidat').all();
return $input.all().map((it, i) => {
  const k = kand[i].json;
  const ris = it.json?.corporate_actions?.right_issue || [];
  const batas = k.is_ri ? String(k.ex_date) : cfg.as_of_date;
  const jumlah = ris.filter((r) => r.ex_date && String(r.ex_date) <= batas).length;
  return { json: { ...k, ri_ke: k.is_ri ? Math.max(jumlah, 1) : null, ri_sebelumnya: k.is_ri ? Math.max(jumlah - 1, 0) : jumlah,
                   riwayat_ri: ris.map((r) => r.ex_date).filter(Boolean).filter((d) => d <= cfg.as_of_date).sort(),
                   data_ri_ok: !it.json?.error } };
});

// Perilaku pemegang saham 12 bulan sampai as_of
const cfg = $('Konfigurasi').first().json;
const C = cfg.config;
const prev = $('Hitung RI ke-berapa').all();
const low = (x) => String(x || '').toLowerCase();
return $input.all().map((it, i) => {
  const k = prev[i].json;
  const rows = it.json?.results || [];
  const jual = rows.filter((r) => r.transaction_type === 'sell');
  let besar = jual.filter((r) => (r.share_percentage_before ?? 0) >= C.MIN_HOLDER_PCT);
  // Pemilik lama yang keluar saat pengambilalihan = bagian dari katalis, bukan buang barang
  let keluarLama = [];
  if (k.is_coc) {
    keluarLama = besar.filter((r) => (r.share_percentage_after ?? 0) < C.MIN_HOLDER_PCT && low(r.holder_name) !== low(k.coc.pembeli));
    besar = besar.filter((r) => !keluarLama.includes(r));
  }
  const jualPct = besar.reduce((s, r) => s + Math.abs(r.share_percentage_transaction ?? 0), 0);
  const menambah = rows.filter((r) => r.transaction_type !== 'sell'
    && (r.share_percentage_after ?? 0) >= C.MIN_HOLDER_PCT
    && (r.share_percentage_after ?? 0) > (r.share_percentage_before ?? 0));
  const grup = [...new Set([...(k.coc?.grup || []), ...rows.flatMap((r) => r.idx_conglomerates_group_slug || [])].filter(Boolean))];
  return { json: { ...k,
    owner: { filings_terbaca: rows.length, jual_pct: +jualPct.toFixed(2),
             penjual_besar: [...new Set(besar.map((r) => r.holder_name).filter(Boolean))],
             pemilik_lama_keluar: [...new Set(keluarLama.map((r) => r.holder_name).filter(Boolean))],
             pemegang_menambah: [...new Set(menambah.map((r) => r.holder_name).filter(Boolean))],
             grup_konglomerasi: grup } } };
});

// Ringkas berita per kandidat untuk dibaca AI
const prev = $('Analisis Owner').all();
const fmt = (v) => (v == null ? '-' : v);
return $input.all().map((it, i) => {
  const k = prev[i].json;
  const res = (it.json?.results || []).slice(0, 8);
  const berita = res.map((n) => `- [${String(n.timestamp || '').slice(0, 10)}] ${n.title || ''}: ${String(n.body || '').replace(/\s+/g, ' ').slice(0, 350)}`).join('\n');
  const fakta = [
    k.is_ri ? `Right issue ke-${k.ri_ke}, ex-date ${k.ex_date}, harga tebus Rp${fmt(k.price)}, rasio lama:baru ${fmt(k.old_ratio)}:${fmt(k.new_ratio)}, dilusi ${fmt(k.pasar.dilusi)}x, harga tebus vs pasar ${k.pasar.diskon_tebus == null ? '-' : Math.round(k.pasar.diskon_tebus * 100) + '%'}` : null,
    k.is_coc ? `${k.coc.jenis}: ${k.coc.pembeli} ${k.coc.sebelum}% -> ${k.coc.sesudah}% (${k.coc.tanggal})` : null,
    `Kapitalisasi sebelum peristiwa: ${k.pasar.mcap_pra ? 'Rp' + (k.pasar.mcap_pra / 1e9).toFixed(0) + ' miliar' : 'tidak ada data'}`,
  ].filter(Boolean).join('\n');
  return { json: { ...k, jumlah_berita: res.length, berita_ringkas: berita || '(tidak ada berita di periode ini)', fakta_peristiwa: fakta } };
});

// TAHAP 5 — SKOR (100) + GERBANG NARASI. Semua angka point-in-time per as_of.
const cfg = $('Konfigurasi').first().json;
const C = cfg.config;
const prev = $('Siapkan Berita').all();
const parseAI = (t) => {
  const m = String(t || '').match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch (e) { return null; }
};
const hasil = $input.all().map((it, i) => {
  const k = prev[i].json;
  const ai = parseAI(it.json?.text) || { jenis: 'tidak_ada_info', pengendali_kuat: false, red_flags: [], ringkasan: '(klasifikasi AI gagal)' };
  const p = k.pasar, o = k.owner;
  const pemilikKuat = k.owner_whitelist || o.grup_konglomerasi.length > 0 || ai.pengendali_kuat === true;
  const tolak = [], alasan = [];

  // ---- Gerbang (gugur) ----
  if (o.jual_pct >= C.MAX_OWNER_JUAL_PCT) tolak.push(`pemegang besar jual ${o.jual_pct}% dalam 12 bulan`);
  if (k.ekuitas_negatif && !k.is_coc) tolak.push('ekuitas negatif tanpa pengendali baru');
  if (C.TOLAK_JENIS.includes(ai.jenis)) tolak.push(`narasi: ${ai.jenis.replace(/_/g, ' ')}`);
  if (p.dilusi != null && p.dilusi >= C.DILUSI_EKSTREM && !pemilikKuat && !k.is_coc) tolak.push(`dilusi ekstrem ${p.dilusi}x tanpa pengendali kuat`);

  // ---- 1) Katalis (30) ----
  let katalis = 0;
  if (k.is_coc) { katalis = 30; alasan.push(`Katalis: ${k.coc.jenis} ${k.coc.pembeli} ${k.coc.sebelum}%→${k.coc.sesudah}% (+30)`); }
  if (k.is_ri) {
    const v = k.ri_ke === 1 ? 30 : k.ri_ke === 2 ? 20 : 0;
    if (v === 0) alasan.push(`Right issue ke-${k.ri_ke}, biasanya tidak signifikan (0)`);
    else if (v > katalis) { katalis = v; alasan.push(`Katalis: right issue ke-${k.ri_ke} (+${v})`); }
    else alasan.push(`Right issue ke-${k.ri_ke} (sudah tercakup)`);
  }
  if (katalis === 0) tolak.push('tidak ada katalis yang memenuhi syarat');

  // ---- 2) Komitmen pengendali (25) ----
  let komit = 0;
  const d = k.is_ri ? p.diskon_tebus : p.harga_akuisisi_vs_pasar;
  if (d == null) { komit += 5; alasan.push('Harga tebus/akuisisi vs pasar tidak bisa dihitung (+5 netral)'); }
  else if (d >= -0.10) { komit += 10; alasan.push(`Harga ${k.is_ri ? 'tebus' : 'akuisisi'} ${Math.round(d * 100)}% vs pasar: pengendali berani bayar wajar (+10)`); }
  else if (d >= -0.35) { komit += 6; alasan.push(`Diskon ${Math.round(d * 100)}% (+6)`); }
  else if (d >= -0.60) { komit += 3; alasan.push(`Diskon dalam ${Math.round(d * 100)}% (+3)`); }
  else alasan.push(`Diskon sangat dalam ${Math.round(d * 100)}% (0)`);
  if (o.filings_terbaca === 0) { komit += 5; alasan.push('Tidak ada data transaksi pemegang saham 12 bln (+5 netral)'); }
  else if (o.jual_pct === 0) { komit += 10; alasan.push('Pemegang besar tidak jual 12 bln (+10)'); }
  else if (o.jual_pct < C.MAX_OWNER_JUAL_PCT) { komit += 5; alasan.push(`Pemegang besar jual ${o.jual_pct}% (+5)`); }
  if (o.pemegang_menambah.length) { komit += 5; alasan.push(`Pemegang besar menambah: ${o.pemegang_menambah.slice(0, 2).join(', ')} (+5)`); }
  if (o.pemilik_lama_keluar.length) alasan.push(`Pemilik lama keluar saat pengambilalihan: ${o.pemilik_lama_keluar.join(', ')} (bukan buang barang)`);

  // ---- 3) Kualitas pemilik (15) ----
  let pemilik = 0;
  if (k.owner_whitelist) { pemilik = 15; alasan.push('Owner di whitelist (+15)'); }
  else if (o.grup_konglomerasi.length) { pemilik = 15; alasan.push(`Grup konglomerasi ${o.grup_konglomerasi.join(', ')} (+15)`); }
  else if (ai.pengendali_kuat === true) { pemilik = 8; alasan.push(`Berita: pengendali kuat (${ai.pengendali || '-'}) (+8)`); }

  // ---- 4) Ruang tumbuh (15) ----
  let ruang = 0;
  if (p.mcap_pra == null) alasan.push('Kapitalisasi tidak diketahui (0)');
  else {
    const t = p.mcap_pra / 1e12;
    ruang = t <= 0.5 ? 15 : t <= 2 ? 10 : t <= 5 ? 5 : 0;
    alasan.push(`Kapitalisasi sebelum peristiwa Rp${t.toFixed(2)} T (+${ruang})`);
  }

  // ---- 5) Arah fundamental (10) ----
  let fund = 0;
  if (k.tumbuh) { fund = 10; alasan.push(`Pendapatan ${k.fundamental_tahun} naik >= ${C.GROWTH_MIN * 100}% (+10)`); }
  else if (k.turnaround) { fund = 10; alasan.push(`Laba ${k.fundamental_tahun} berbalik dari rugi (+10)`); }

  // ---- 6) Timing / anti-FOMO (5) ----
  let timing = 0;
  if (p.kenaikan_90h == null) alasan.push('Data harga 90 hari tidak ada (0)');
  else if (p.kenaikan_90h <= 2) { timing = 5; alasan.push(`Harga ${p.kenaikan_90h}x dari titik terendah 90 hari (+5)`); }
  else if (p.kenaikan_90h <= 3) { timing = 2; alasan.push(`Harga ${p.kenaikan_90h}x dari titik terendah 90 hari (+2)`); }
  else alasan.push(`Harga sudah ${p.kenaikan_90h}x dari titik terendah 90 hari, rawan FOMO (0)`);

  const skor = katalis + komit + pemilik + ruang + fund + timing;
  if (skor < C.SKOR_MINIMUM) tolak.push(`skor ${skor} < ${C.SKOR_MINIMUM}`);
  return { ...k, ai, skor, skor_rinci: { katalis, komitmen: komit, pemilik, ruang_tumbuh: ruang, fundamental: fund, timing },
           alasan, tolak, lolos: tolak.length === 0, mode: cfg.mode, as_of_date: cfg.as_of_date };
});
const lolos = hasil.filter((h) => h.lolos);
if (!lolos.length) {
  return [{ json: { _empty: true, tahap: 'skor', stats: hasil[0]?.stats, ditolak_gerbang: hasil[0]?.ditolak_gerbang || [],
    dicek: hasil.map((h) => ({ symbol: h.symbol, skor: h.skor, tolak: h.tolak, jenis: h.ai.jenis })) } }];
}
return lolos.map((h) => ({ json: { ...h, dicek_lain: hasil.filter((x) => !x.lolos).map((x) => ({ symbol: x.symbol, skor: x.skor, tolak: x.tolak })) } }));

// Evaluasi backtest: kinerja 90 hari SETELAH sinyal (tidak memengaruhi skor)
const prev = $('Skor').all();
const parse = (j) => {
  if (!j || j.error) return null;
  let raw = j.raw ?? j.data ?? j;
  if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { return null; } }
  return Array.isArray(raw) ? raw : (raw?.results || null);
};
return $input.all().map((it, i) => {
  const k = prev[i].json;
  const rows = (parse(it.json) || []).filter((r) => r && r.close > 0).sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const entry = k.pasar?.harga_asof;
  let kinerja = null;
  if (rows.length && entry) {
    const last = rows[rows.length - 1];
    const maks = Math.max(...rows.map((r) => r.close));
    kinerja = { sampai: last.date, hari: rows.length, return_pct: Math.round((last.close / entry - 1) * 100), puncak_pct: Math.round((maks / entry - 1) * 100) };
  }
  return { json: { ...k, kinerja } };
});

const cfg = $('Konfigurasi').first().json;
const tz = 'Asia/Jakarta';
const now = DateTime.now().setZone(tz);
const ambil = (n) => { try { return $(n).all().map((i) => i.json); } catch (e) { return null; } };
const stats = ambil('Gabung kandidat')?.[0]?.stats || {};
const gerbang = ambil('Gerbang Pasar');
const skorAll = ambil('Skor');
const ditolakGerbang = gerbang?.[0]?.ditolak || gerbang?.[0]?.ditolak_gerbang || [];
const dicek = skorAll?.[0]?._empty ? (skorAll[0].dicek || []) : (skorAll?.[0]?.dicek_lain || []);

let sinyal = [];
const inp = $input.all().map((i) => i.json);
if (inp.length && typeof inp[0].text === 'string') {
  const menang = (ambil('Gabung Kinerja') || ambil('Skor') || []).filter((j) => j.lolos);
  sinyal = menang.map((s, i) => ({ ...s, tesis: (inp[i]?.text || '').trim() || '(tesis AI gagal dibuat)' }));
}

const kunci = (s) => `${s.symbol}|${s.ex_date || ''}|${s.coc?.tanggal || ''}`;
let baru = sinyal;
if (cfg.mode === 'live') {
  const st = $getWorkflowStaticData('global');
  st.terkirim = st.terkirim || {};
  baru = sinyal.filter((s) => !st.terkirim[kunci(s)]);
  baru.forEach((s) => { st.terkirim[kunci(s)] = now.toISO(); });
}

const label = cfg.mode === 'backtest'
  ? `🧪 BACKTEST (as of ${cfg.as_of_date})`
  : `📋 Andry Hakim Screener — ${now.toFormat('dd LLL yyyy HH:mm')} WIB`;
const T = (x) => (x == null ? '-' : 'Rp' + (x / 1e12).toFixed(2) + ' T');
const blok = (s) => {
  const r = s.skor_rinci, p = s.pasar;
  const kat = [];
  if (s.is_ri) kat.push(`RI ke-${s.ri_ke} (ex ${s.ex_date}, tebus Rp${s.price ?? '-'}, rasio ${s.old_ratio ?? '?'}:${s.new_ratio ?? '?'})`);
  if (s.is_coc) kat.push(`${s.coc.jenis}: ${s.coc.pembeli} ${s.coc.sebelum}%→${s.coc.sesudah}%`);
  return [
    `▶ ${s.symbol} — skor ${s.skor}/100`,
    `  katalis ${r.katalis}/30 · komitmen ${r.komitmen}/25 · pemilik ${r.pemilik}/15 · ruang ${r.ruang_tumbuh}/15 · fundamental ${r.fundamental}/10 · timing ${r.timing}/5`,
    `Katalis: ${kat.join(' + ')}`,
    `Pasar: kapitalisasi pra-peristiwa ${T(p.mcap_pra)} | naik ${p.kenaikan_90h ?? '-'}x dari low 90h | harga tebus vs pasar ${p.diskon_tebus == null ? '-' : Math.round(p.diskon_tebus * 100) + '%'}`,
    `Narasi berita: ${s.ai?.jenis || '-'}${s.ai?.ringkasan ? ' — ' + s.ai.ringkasan : ''}`,
    s.kinerja ? `📈 90 hari kemudian: ${s.kinerja.return_pct >= 0 ? '+' : ''}${s.kinerja.return_pct}% (puncak +${s.kinerja.puncak_pct}%)` : null,
    s.tesis, '',
  ].filter((x) => x !== null).join('\n');
};
const ringkasTolak = [
  ...ditolakGerbang.map((d) => `${d.symbol} (${d.alasan})`),
  ...dicek.map((d) => `${d.symbol} (${(d.tolak || []).join('; ')})`),
].slice(0, 8);

let pesan;
if (baru.length) {
  pesan = [label, `${baru.length} emiten lolos:`, '', ...baru.map(blok),
    ringkasTolak.length ? `Gugur: ${ringkasTolak.join(' | ')}` : null,
    '⚠️ Terinspirasi kerangka publik Andry Hakim, bukan rekomendasi beliau dan bukan saran investasi.'].filter((x) => x !== null).join('\n');
} else {
  pesan = [label,
    cfg.mode === 'live' ? '0 emiten lolos hari ini.' : '0 emiten lolos pada tanggal ini.',
    `Right issue di jendela ${cfg.calStart} s/d ${cfg.calEnd}: ${stats.ri_dalam_jendela ?? 0}`,
    `Pengambilalihan pihak baru: ${stats.akuisisi_terdeteksi ?? 0} (diabaikan karena pihak lama/akuisisi oleh emiten: ${stats.akuisisi_diabaikan ?? 0})`,
    `Kandidat dicek: ${stats.kandidat ?? 0} | Filings dipindai: ${stats.filings_dibaca ?? 0}${stats.filings_total_tersedia != null ? ' dari ' + stats.filings_total_tersedia : ''}`,
    ringkasTolak.length ? `Gugur: ${ringkasTolak.join(' | ')}` : null,
    sinyal.length && !baru.length ? 'Sinyal yang lolos sudah pernah dikirim sebelumnya.' : null,
    stats.kalender_error ? '⚠️ Gagal mengambil kalender corporate action.' : null,
  ].filter(Boolean).join('\n');
}
return [{ json: {
  timestamp: now.toISO(), mode: cfg.mode, as_of_date: cfg.as_of_date,
  ri_dalam_jendela: stats.ri_dalam_jendela ?? 0, akuisisi_terdeteksi: stats.akuisisi_terdeteksi ?? 0,
  kandidat: stats.kandidat ?? 0, lolos: baru.length,
  simbol_lolos: baru.map((s) => s.symbol + (s.kinerja ? ` (${s.kinerja.return_pct >= 0 ? '+' : ''}${s.kinerja.return_pct}% 90h)` : '')).join(', '),
  pesan: pesan.slice(0, 4000),
} }];
